-- Candidate only. No issuer/provisioning route, credential or real authority.
-- Synthetic-exclusive custody is deliberate: do not copy a live Mac permit here.
CREATE TABLE sites_execution_policies(id TEXT PRIMARY KEY,workspace TEXT NOT NULL,account_id TEXT NOT NULL,policy_json TEXT NOT NULL,limits_json TEXT NOT NULL,history_json TEXT NOT NULL,history_day TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),revoked_at INTEGER,custody TEXT NOT NULL CHECK(custody='SYNTHETIC_EXCLUSIVE'),FOREIGN KEY(workspace,account_id) REFERENCES sites_account_details(workspace,account_id));
CREATE TABLE sites_execution_permits(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES publisher_jobs(id),policy_id TEXT NOT NULL REFERENCES sites_execution_policies(id),scope_json TEXT NOT NULL,scope_hash TEXT NOT NULL,binding_json TEXT NOT NULL,authorization_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('AVAILABLE','CONSUMED','REVOKED')),issued_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>issued_at),attempt_id TEXT,prior_duplicate INTEGER NOT NULL CHECK(prior_duplicate IN (0,1)));
CREATE TABLE sites_execution_claims(job_id TEXT PRIMARY KEY REFERENCES publisher_jobs(id),permit_id TEXT NOT NULL UNIQUE REFERENCES sites_execution_permits(id),plan_id TEXT NOT NULL UNIQUE REFERENCES sites_upload_plans(id),attempt_id TEXT NOT NULL UNIQUE,workspace TEXT NOT NULL,account_id TEXT NOT NULL,platform TEXT NOT NULL CHECK(platform='facebook'),budget_key TEXT NOT NULL,scope_hash TEXT NOT NULL,snapshot_hash TEXT NOT NULL,content_id TEXT NOT NULL,content_revision INTEGER NOT NULL,day TEXT NOT NULL,dedup_key TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('RESERVED','SUBMITTING','UNKNOWN','SETTLED','RELEASED')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(budget_key,dedup_key),FOREIGN KEY(workspace,account_id) REFERENCES sites_account_details(workspace,account_id));
CREATE INDEX sites_execution_budget ON sites_execution_claims(budget_key,day,state);
CREATE TABLE sites_execution_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT NOT NULL REFERENCES publisher_jobs(id),permit_id TEXT NOT NULL REFERENCES sites_execution_permits(id),attempt_id TEXT,event TEXT NOT NULL,detail_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER sites_execution_audit_no_update BEFORE UPDATE ON sites_execution_events BEGIN SELECT RAISE(ABORT,'EXECUTION_AUDIT_IMMUTABLE'); END;
CREATE TRIGGER sites_execution_audit_no_delete BEFORE DELETE ON sites_execution_events BEGIN SELECT RAISE(ABORT,'EXECUTION_AUDIT_IMMUTABLE'); END;
